import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getRoundHandler } from "../handlers/getRoundHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";

type Data = Awaited<ReturnType<typeof getRoundHandler>>;

export function useGetRound(
  roundId: FactFoldRoundEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getRound", roundId],
    queryFn: () => getRoundHandler(roundId),
    ...options,
  });
}
